code_state.current_implementation:

export class SyncManager {
  private projectPath: string;
  private webcontainer: WebContainer | null = null;
  private excludedPatterns: string[] = DEFAULT_EXCLUDED_PATTERNS;
  private syncQueue: Map<string, FileSyncOperation> = new Map();
  private syncInProgress: boolean = false;

  constructor(projectPath: string) {
    this.projectPath = projectPath;
  }

  async syncToWebContainer(): Promise<void> {
    if (this.syncInProgress) {
      console.warn('Sync already in progress, skipping');
      return;
    }
    this.syncInProgress = true;
    try {
      // ISSUE: Full directory tree scan every time
      const allFiles = await this.scanDirectoryTree(this.projectPath);
      const operations: FileSyncOperation[] = [];

      for (const file of allFiles) {
        const relativePath = path.relative(this.projectPath, file.path);
        if (this.shouldExclude(relativePath)) continue;

        operations.push({
          type: 'write',
          path: relativePath,
          content: file.content
        });
      }

      await this.batchSync(operations);
    } finally {
      this.syncInProgress = false;
    }
  }

  async scanDirectoryTree(dirPath: string): Promise<LocalFileRecord[]> {
    const files: LocalFileRecord[] = [];
    const entries = await fs.promises.readdir(dirPath, { withFileTypes: true });

    for (const entry of entries) {
      const fullPath = path.join(dirPath, entry.name);
      if (this.shouldExclude(entry.name)) continue;

      if (entry.isDirectory()) {
        const subFiles = await this.scanDirectoryTree(fullPath);
        files.push(...subFiles);
      } else if (entry.isFile()) {
        const content = await fs.promises.readFile(fullPath, 'utf-8');
        const stat = await fs.promises.stat(fullPath);
        files.push({
          path: fullPath,
          name: entry.name,
          content,
          mtime: stat.mtimeMs,
          size: stat.size
        });
      }
    }
    return files;
  }
}

